import{_ as r,o as a,c as t,ag as n}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年8月6日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-06.md","filePath":"science-log/src/reconstructed/2026-08-06.md"}'),o={name:"science-log/src/reconstructed/2026-08-06.md"};function s(i,e,g,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="🔬-科学快报-2026年8月6日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月6日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月6日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月6日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202608060000 TO 202608062359]</code>（cs.AI）｜ 重建日：2026-11-05 当日为周四（2026-08-06）：CrossRef 返回 Nature 该日 7 条记录，其中仅 1 条为 <code>s41586</code> 研究论文（<code>10.1038/s41586-026-10953-2</code>），其余 6 条为 <code>d41586</code> 新闻/Briefing，已按规则丢弃；Science 系当日 44 条记录（含大量 <code>science.z*</code> 新闻与 Podcast，已剔除）；PNAS 当日 9 条。故科学 5 篇取自 Nature 1 + Science 3 + PNAS 1。</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🌀-ai-业务化台风预报-对流尺度的「粗网格」也能打赢区域模式" tabindex="-1">🌀 AI 业务化台风预报：对流尺度的「粗网格」也能打赢区域模式 <a class="header-anchor" href="#🌀-ai-业务化台风预报-对流尺度的「粗网格」也能打赢区域模式" aria-label="Permalink to &quot;🌀 AI 业务化台风预报：对流尺度的「粗网格」也能打赢区域模式&quot;">​</a></h3><p><strong>Operational tropical cyclone forecasting with AI</strong><em>Nature（2026）</em></p><p>热带气旋是最危险也最昂贵的天气现象之一，而路径、强度、尺度三者同时报准长期是业务预报的痛点。Google DeepMind 的 F. Alet、T. R. Andersson、I. Price、S. Markou 等提出 <strong>WeatherNext Cyclones（WN-C）</strong>：一个业务化的 AI 集合预报模型，用全球分析场加历史热带气旋数据库训练，直接生成 15 天、最多 <strong>1,000 成员</strong>的全球天气与气旋情景集合。在 2023–2025 年的气旋样本上，其路径、强度与风圈半径预报相对主流业务模式平均取得 <strong>1 天以上</strong>的预报时效优势——相当于过去十年业务模式发展的总进步量。更反直觉的是它用的输入比区域模式<strong>粗几个数量级</strong>，说明高分辨率并非强度预报的必要前提，粗分辨率大气场里本就存在比此前认为更多的强度信号；把 WN-C 并入加权平均共识集合能显著提升技巧。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10953-2" target="_blank" rel="noreferrer">10.1038/s41586-026-10953-2</a></p><h3 id="🧲-悬浮磁体磁强计-32-ft-√hz-室温、地磁场下可用" tabindex="-1">🧲 悬浮磁体磁强计：32 fT/√Hz，室温、地磁场下可用 <a class="header-anchor" href="#🧲-悬浮磁体磁强计-32-ft-√hz-室温、地磁场下可用" aria-label="Permalink to &quot;🧲 悬浮磁体磁强计：32 fT/√Hz，室温、地磁场下可用&quot;">​</a></h3><p><strong>Levitated sensor for magnetometry in ambient environment</strong><em>Science（2026）</em></p><p>悬浮微粒系统因无机械接触、损耗低、隔离性好而成为精密传感的新平台，但室温悬浮方案此前主要对<strong>加速度</strong>敏感，与高灵敏磁测量难以兼容。W. Ji、C. Xu、G. Qu、D. Budker 演示了一个<strong>抗磁稳定 + 磁悬浮</strong>的磁体磁强计：用光学方法读出悬浮磁体的运动。实测灵敏度达 <strong>32 fT/√Hz</strong>，与超导量子干涉器件（SQUID）和原子磁强计同一量级，却<strong>不需要低温</strong>，且能在地磁场环境下工作。这把「超导级灵敏度」从液氦环境解放出来，直接指向可穿戴脑磁（MEG）、无屏蔽材料磁化检测与基础物理的洛伦兹不变性检验等场景——同日 Nature 的新闻版也专门评述了这项进展。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adx1707" target="_blank" rel="noreferrer">10.1126/science.adx1707</a></p><h3 id="🧬-用基因组语言模型「生成」活噬菌体" tabindex="-1">🧬 用基因组语言模型「生成」活噬菌体 <a class="header-anchor" href="#🧬-用基因组语言模型「生成」活噬菌体" aria-label="Permalink to &quot;🧬 用基因组语言模型「生成」活噬菌体&quot;">​</a></h3><p><strong>Generative design of bacteriophages with genome language models</strong><em>Science（2026）</em></p><p>重要生物学功能往往不由单个基因决定，而由整个基因组编码的复杂互作决定。S. H. King、C. L. Driscoll、D. B. Li、D. Guo、M. E. Wilkinson、B. L. Hie 等报告了<strong>首次用基因组语言模型生成完整噬菌体基因组</strong>：以噬菌体 ΦX174 为设计模板，生成具备目标宿主嗜性的基因组。实验测试得到 <strong>16 株可存活</strong>、适应度谱各异的噬菌体；冷冻电镜证实其中一株使用的是<strong>演化上相距甚远的 DNA 包装蛋白</strong>来组装衣壳。由生成噬菌体组成的鸡尾酒能迅速压制对 ΦX174 已产生抗性的大肠杆菌，展示了「AI 生成噬菌体疗法」对抗快速演化病原体的路径。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aec2657" target="_blank" rel="noreferrer">10.1126/science.aec2657</a></p><h3 id="🧠-θ-扫掠是「注意力」-导航回路按当下需求动态调参" tabindex="-1">🧠 θ 扫掠是「注意力」：导航回路按当下需求动态调参 <a class="header-anchor" href="#🧠-θ-扫掠是「注意力」-导航回路按当下需求动态调参" aria-label="Permalink to &quot;🧠 θ 扫掠是「注意力」：导航回路按当下需求动态调参&quot;">​</a></h3><p><strong>Adaptive modulation of theta sweeps in the brain&#39;s navigation circuit</strong><em>Science（2026）</em></p><p>高效导航要求优先采样行为上相关的位置。大鼠的网格细胞与位置细胞群存在 θ 节律下的「扫掠」：以左右交替模式扫描邻近空间，由副下托的方向信号协调，从而在探索时获得均匀的空间覆盖；但扫掠能否按当下需求灵活调节此前未知。A. Z. Vollan、M. F. Schellenberger、R. J. Gardner、M.-B. Moser、E. I. Moser（Kavli 系统神经科学研究所 / NTNU）用自由活动大鼠的大规模 Neuropixels 记录证明：扫掠与方向信号都能<strong>快速动态调制</strong>——追逐时跟踪移动目标、静止时先于定向反应出现、倒退行走时方向反转，且<strong>无需事先学会目标位置</strong>；REM 睡眠中出现类似调制。结论是扫掠构成一种类注意机制，用于选择性采样「以世界为参照」的认知地图。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aef4184" target="_blank" rel="noreferrer">10.1126/science.aef4184</a></p><h3 id="💊-ai-设计的-protac-清除-clip1–ltk-融合蛋白" tabindex="-1">💊 AI 设计的 PROTAC 清除 CLIP1–LTK 融合蛋白 <a class="header-anchor" href="#💊-ai-设计的-protac-清除-clip1–ltk-融合蛋白" aria-label="Permalink to &quot;💊 AI 设计的 PROTAC 清除 CLIP1–LTK 融合蛋白&quot;">​</a></h3><p><strong>AI-driven PROTAC design overcomes oncogenic resilience by eliminating the CLIP1-LTK fusion protein</strong><em>PNAS（2026）</em></p><p>CLIP1–LTK 融合的致癌性不只来自 LTK 激酶活性，还依赖 CLIP1 介导的<strong>多聚化</strong>这一非催化功能；现有 ALK 抑制剂只压激酶，脚手架功能原封不动，耐药随之而来。S. Chen、H. Duan、S. Zhong、J. Ge、P. Pan 等把三元复合物预测的深度学习模型与基于结构的分子优化结合，设计出首个体内可用的 CLIP1–LTK 降解剂 <strong>DCL05</strong>：口服可吸收，降解效力达 <strong>DC50 = 40 pM</strong>，并在体外与体内广谱优于现有激酶抑制剂（含多种 LTK 耐药相关突变）。其意义是把「抑制一个活性」升级为「清除整个蛋白」，为激酶驱动肿瘤的获得性耐药提供了结构引导的 PROTAC 流水线。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2535979123" target="_blank" rel="noreferrer">10.1073/pnas.2535979123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🔓-从黑盒里「撬出」glu-前馈块-反对偶法逐级分离" tabindex="-1">🔓 从黑盒里「撬出」GLU 前馈块：反对偶法逐级分离 <a class="header-anchor" href="#🔓-从黑盒里「撬出」glu-前馈块-反对偶法逐级分离" aria-label="Permalink to &quot;🔓 从黑盒里「撬出」GLU 前馈块：反对偶法逐级分离&quot;">​</a></h3><p><strong>Cryptanalytic Extraction of Isolated Bias-Free GLU Feed-Forward Blocks by Antipodal Separation</strong><em>arXiv（2026）</em></p><p>权重提取（cryptanalytic extraction）此前在 ReLU 网络、逐元素激活（GELU/SiLU）网络以及 Transformer 末层投影矩阵上都有成果，但都拿不到现代语言模型里大量使用的<strong>无偏置 GLU 前馈块</strong>——它在每个隐单元内把一条激活后的线性投影与另一条学到的线性投影相乘，这种双支结构不在前述网络类与末层设定的覆盖范围内。Chunhui Shi、Xinwen Fu 给出一个构造性的多阶段前向查询恢复原语：用有限差分曲率给出门控方向候选，再用 <strong>x 与 −x 的成对观测</strong>分离门控幅度、朝向与值支耦合。在高精度目标上，六个 Qwen 层、一个 8,192 单元的 Llama 子问题与一个全维 Gemma 块都达到<strong>中位验证误差低于 1%</strong>；四种有限精度配置仍保持中位误差 5% 以内，但没有一种能复现每一个存储权重。作者明确划界：这是隔离块实验，尚非端到端模型 API 攻击，如何从最终输出反推内部块响应仍未解。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.06631" target="_blank" rel="noreferrer">2608.06631</a></p><h3 id="📐-最优-agnostic-pac-学习-样本复杂度在常数因子内闭合" tabindex="-1">📐 最优 agnostic PAC 学习：样本复杂度在常数因子内闭合 <a class="header-anchor" href="#📐-最优-agnostic-pac-学习-样本复杂度在常数因子内闭合" aria-label="Permalink to &quot;📐 最优 agnostic PAC 学习：样本复杂度在常数因子内闭合&quot;">​</a></h3><p><strong>An Optimal Agnostic PAC Algorithm</strong><em>arXiv（2026）</em></p><p>设 H ⊆ {−1,+1}^X 是 VC 维为 d ≥ 1 的假设类，L 为二分类风险、L* 为类内最小风险。Markus Engelund Mathiasen、Jian Qian、Nikita Zhivotovskiy 构造出一个学习器，从 n 个 i.i.d. 样本出发，对任意 0 &lt; δ ≤ 1/2，以至少 1−δ 的概率满足 L(ĥ) ≤ L* + 7×10⁸·(√(L*(d+log(1/δ))/n) + (d+log(1/δ))/n)。这条界在<strong>每一个固定 L</strong>* 处都匹配 Devroye、Györfi、Lugosi（1996）给出的下界，因此把 agnostic PAC 学习的样本复杂度在<strong>通用常数因子内彻底定死</strong>。系数 7×10⁸ 显然不是实用的，但这类结果的价值在于判定「最优速率是什么形状」——它说明可实现性（realizable）与 agnostic 之间的差距不是 log 因子，而是 √L* 这一项，而这一项此前没有匹配的算法。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.06363" target="_blank" rel="noreferrer">2608.06363</a></p><h3 id="🪜-stepjack-把恶意目标拆成无害小步-多步间接提示注入打穿电脑使用智能体" tabindex="-1">🪜 StepJack：把恶意目标拆成无害小步，多步间接提示注入打穿电脑使用智能体 <a class="header-anchor" href="#🪜-stepjack-把恶意目标拆成无害小步-多步间接提示注入打穿电脑使用智能体" aria-label="Permalink to &quot;🪜 StepJack：把恶意目标拆成无害小步，多步间接提示注入打穿电脑使用智能体&quot;">​</a></h3><p><strong>StepJack: Benchmarking Computer-Use Agent Safety Against Multi-Step Indirect Prompt Injection</strong><em>arXiv（2026）</em></p><p>电脑使用智能体（CUA）面临间接提示注入：对抗指令被埋在网页等环境里。Zhuoxin Zhan、Akbar Rafiey、Avery Ma、Leila Pishdad、Layla El Asri 提出<strong>多步间接提示注入</strong>这一新攻击类：把对抗目标分解成多个看起来无害的子步骤，散布在智能体导航路径上的一条页面链中；并给出自动分解流水线，约束是「子步骤合起来必须达成原目标」，同时优化每个子步骤的<strong>无害程度</strong>。据此构建基准 <strong>StepJack</strong>（480 个测试例），评测六个前沿 CUA：在固定分解深度下，多步攻击使六个中的三个成功率上升，最高 <strong>+31.2 个百分点</strong>（GPT-5.4-mini 从单步 41.7% 升到三步 72.9%）；能可靠沿参考链执行的五个智能体平均从 31.3% 升至 36.9%。这条结果说明「单步注入」防御的评测范式系统性低估了风险：威胁模型必须按<strong>轨迹</strong>而非按单页来定义。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.06477" target="_blank" rel="noreferrer">2608.06477</a></p><h3 id="⏹️-av-aivat-证据够了就停-智能体评测省-74-倍" tabindex="-1">⏹️ AV-AIVAT：证据够了就停，智能体评测省 74 倍 <a class="header-anchor" href="#⏹️-av-aivat-证据够了就停-智能体评测省-74-倍" aria-label="Permalink to &quot;⏹️ AV-AIVAT：证据够了就停，智能体评测省 74 倍&quot;">​</a></h3><p><strong>AV-AIVAT: 74x Cheaper Agent Evaluation with Certified Anytime-Valid Stopping in Imperfect-Information Games</strong><em>arXiv（2026）</em></p><p>判断两个智能体谁更强，本质是「打到技巧压过运气为止」，而每局都要花推理费或专家时间。固定预算评测要么在结论已定后继续付费，要么在还分不开时就停；朴素地「看置信区间、到了就停」则会让名义置信水平失效。Boning Li、Yu Chen、Longbo Huang 把三步合成一体：AIVAT 用条件均值为零的修正降低不完全信息博弈的方差（15 组 LLM 智能体配置、<strong>71,439 手</strong>一对一无限注德州扑克，中位方差降 <strong>54 倍</strong>），但它不告诉你何时停；再与持续监控的<strong>置信序列（CS）<strong>结合成 anytime-valid 版本，且在线价值模型只用</strong>过去</strong>的牌局学习，避免任何一局给自己的修正「打分」。在 95% 名义水平、±1 大盲的目标精度下，未修正的原始结果需要<strong>中位 74 倍</strong>的手数才能停；精确的有限样本认证改用经验 Bernstein CS，需对修正后收益的界有独立依据，作者对 Leduc 扑克给出结构性证明，并刻画了由下注上限与该界共同决定的宽度地板。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.06362" target="_blank" rel="noreferrer">2608.06362</a></p><h3 id="🧾-生产环境-352-万次改动-ai-写的-c-有自己的质量剖面" tabindex="-1">🧾 生产环境 352 万次改动：AI 写的 C++ 有自己的质量剖面 <a class="header-anchor" href="#🧾-生产环境-352-万次改动-ai-写的-c-有自己的质量剖面" aria-label="Permalink to &quot;🧾 生产环境 352 万次改动：AI 写的 C++ 有自己的质量剖面&quot;">​</a></h3><p><strong>Characterizing the Quality Profile of AI-Generated C++ in Production</strong><em>arXiv（2026）</em></p><p>AI 编程助手提升交付速度已无争议，但对<strong>已上线软件质量</strong>的影响在工业流程里很难测，因为缺少可观测性。Michael Tran、Fred Lewis、Kun Yang、Saksham Thakur、Aditya Kini 等在一家支撑数十亿用户的大型企业内部做了大规模实证：2025 年 4 月至 2026 年 4 月，追踪棕色地带代码库中 <strong>352 万次代码改动</strong>，逐行对比 AI 生成与人类编写的 C++。结果是 AI 代码有清晰可辨的质量剖面——更高的接口与耦合负担、拷贝与分配开销，以及偏好显式循环而非优化过的标准库 API；这些差异转化为真实下游成本：评审负担上升，<strong>计算资源消耗增加 5–8%</strong>。但作者也给出可操作的解：向模型提供<strong>分类学指导的定向反馈</strong>，可使目标静态分析告警减少 <strong>11.1%</strong>，并改善计算效率。价值在于把「AI 代码好还是坏」的口水战换成了一个可度量的剖面，且证明缺陷是可被针对性反馈削掉的。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.06640" target="_blank" rel="noreferrer">2608.06640</a></p><blockquote><p>📅 日期：2026-08-06 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 期号：原期号不可考（重建时不推测），标为（第 ? 期 · 事后重建版）</p></blockquote>',45)])])}const u=r(o,[["render",s]]);export{d as __pageData,u as default};
